import type { AffixInfo } from '../types';
import affixData from './game/affixes.json';

// Generated by tools/datamine from DT_ModifierInfo and CT_DungeonModifiers. Only affixes in the
// live rotation are exported.
export const affixes = affixData as AffixInfo[];

export const affixById: Record<string, AffixInfo> = Object.fromEntries(affixes.map((a) => [a.id, a]));

/** Mini-boss affixes; at most one is active in a run. */
export const WINTER_BOSSES = affixes.filter((a) => a.kind === 'miniboss').map((a) => a.id);

/** Kill score multiplier for Empowered Minions. */
export const EMPOWERED_MULTIPLIER = affixById.empowered?.scoreMultiplier ?? 3;
/** Health multiplier for Empowered Minions. */
export const EMPOWERED_HEALTH = affixById.empowered?.healthMultiplier ?? 2;
/** Shadow Orbs needed to summon an Emissary of the Shadow Lord. */
export const SHADOW_ORBS_PER_EMISSARY = affixById['shadow-lord']?.orbsPerEmissary ?? 30;
